export type TranslationKey = keyof typeof catalog;
let activeLanguage: AppLanguage = 'en';
export function setTranslationLanguage(language: AppLanguage) { activeLanguage = language; }
export function getTranslationLanguage() { return activeLanguage; }
export function translate(key: TranslationKey, params?: Record<string, string | number>, language = activeLanguage): string {
  const value = language === 'en' ? englishTemplates[key] ?? key : catalog[key][language === 'hi' ? 0 : 1];
  return interpolate(value, params);
}
const englishTemplates: Partial<Record<TranslationKey, string>> = {
  missedTreeDays: '{count} incomplete days. Your tree loses one level per day, down to zero. Complete both practices to grow again.',
  androidSettingsFor: 'Opens Android settings for {label}',
  openedSettings: 'Opened {destination}. Return here to recheck access.', manualInstructions: 'Follow the manual instructions below.', alarmSavedTime: '{days} at {time}', alarmTimePeriod: '{value} time period', progressAccessibility: "Today's ritual progress: {count} of 2 complete",
  requirementsReady: '{count} of 3 required settings ready', openTask: 'Open {title}',
  completedSection: 'Completed · {count}', pendingCount: '{count} pending', editTask: 'Edit {title}',
  streakDays: '{count}-day streak', completedCount: '{done} of {total} complete', chapterVerse: 'Chapter {chapter} · Shloka {verse}',
  alarmIn: 'Alarm rings in {duration}', daysCount: '{count} days', hoursCount: '{count} hrs', minutesCount: '{count} min',
};
/** For known system labels assembled by stores; unknown text is preserved, never guessed. */
export function translateText(text: string | undefined, language = activeLanguage): string {
  if (text === undefined) return '';
  if (text.startsWith('Error: ')) return translateText(text.slice(7), language);
  if (text.includes('\n')) return text.split('\n').map(line => translateText(line, language)).join('\n');
  return Object.hasOwn(catalog, text) ? translate(text as TranslationKey, undefined, language) : text;
}
